const overdueTasksAtom = atom((get) => {
  const allTasks = get(tasksWithStartAtom);
  const today = dayjs();
  return allTasks.filter((task) => {
    if (!task.start || task.status === "done")
      return false;
    if (task.end)
      return task.end.isBefore(today, "day");
    return task.start.isBefore(today, "day");
  });
});

const uploadIcsHttp = async ({ repo, token, file }) => {
  return new Promise((resolve, reject) => {
    fetch(`https://agenda-ics.haydenhayden.com`, {
      method: "POST",
      body: JSON.stringify({
        repo,
        token,
        file
      })
    }).then(async (response) => {
      console.log("upload ics response", response);
      const data = await response.json();
      if (!response.ok) {
        reject(data);
      }
      resolve(data);
    }).catch((err) => {
      reject(err);
    });
  });
};

const transformAgendaTaskToICSEvent = (task, graphName) => {
  const { start, allDay, end, estimatedTime, project, rawBlock, showTitle } = task;
  let common = {
    title: showTitle,
    start: genDateArray(start, allDay),
    calName: "Agenda",
    productId: "haydenull/ics",
    description: `project: ${project.originalName}

Logseq Deep Link: logseq://graph/${graphName}?block-id=${rawBlock.uuid}`
  };
  if (task.rrule) {
    const rruleInstance = getRRuleInstance(task.rrule);
    common = {
      ...common,
      recurrenceRule: rruleInstance.toString().split("\n").find((l) => l.startsWith("RRULE:"))?.replace("RRULE:", "") || ""
    };
  }
  let type = "day-event";
  if (allDay === false) {
    type = "time-event";
  } else if (end) {
    type = "multi-days-event";
  }
  switch (type) {
    case "multi-days-event":
      return {
        ...common,
        end: genDateArray(end.add(1, "day"), allDay)
      };
    case "time-event":
      return {
        ...common,
        duration: { minutes: estimatedTime ?? DEFAULT_ESTIMATED_TIME }
      };
    case "day-event":
      return {
        ...common,
        end: common.start
      };
  }
};
function genDateArray(day, allDay) {
  const year = day.year();
  const month = day.month() + 1;
  const date = day.date();
  const hour = day.hour();
  const minute = day.minute();
  return allDay ? [year, month, date] : [year, month, date, hour, minute];
}

